@[simp] lemma lift'_naturality {s : Cone F} {c d : C}
    (f : c ⟶ d) (x' : yoneda.obj d ⟶ s.pt) :
    lift' P c (yoneda.map f ≫ x') = yoneda.map f ≫ lift' P d x'

